import { MeshBasicNodeMaterial, PlaneGeometry, Mesh } from 'three/webgpu';
import { gsap } from 'gsap';

/**
 * Creates a node for Pricing Card 3 Label.
 * @param {object} config - PrismNode configuration.
 * @param {object} ctx - Runtime context.
 * @returns {THREE.Object3D} The node object.
 */
export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Root group for positioning
  const group = new THREE.Group();

  // Parse config for text content
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find(item => item.role === 'headline') || items[0];
  const headlineText = headlineItem?.text || '';

  // Geometry for the plane (matching atlas region dimensions)
  const geometry = new PlaneGeometry(5.12, 3.2); // proportional to 512x320 atlas region

  // Material: MeshBasicNodeMaterial with no initial texture
  const material = new MeshBasicNodeMaterial({
    color: 0x0b0b10, // fallback surface color
  });

  // Create mesh and add to group
  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  // Load the texture asynchronously
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      // No offset/repeat needed if source rect covers full image
      // (source rect is (0,0,512,320) which matches the image dimensions assumed)
      material.map = texture;
      material.needsUpdate = true;
    });
  }

  // Create text using font atlas
  if (headlineText && ctx.fontAtlas) {
    const textOpts = {
      fontSize: 0.34, // headline scene unit size from type scale
      color: '#e8ecf2', // paper color for contrast
      align: 'center',
      maxWidthPx: 4.5, // constrained width in scene units? (approximate)
    };
    const textMesh = ctx.fontAtlas.createText(headlineText, textOpts);
    if (textMesh) {
      // Position text in front of the plane
      textMesh.position.set(0, 0, 0.01);
      group.add(textMesh);
    }
  }

  // Apply scene placement from config
  const pos = config.scenePosition || { x: 3.2, y: 1, z: 0.06 };
  group.position.set(pos.x, pos.y, pos.z);
  if (config.sceneRotation) {
    group.rotation.set(config.sceneRotation.x, config.sceneRotation.y, config.sceneRotation.z);
  }
  if (config.sceneScale) {
    group.scale.set(config.sceneScale.x, config.sceneScale.y, config.sceneScale.z);
  }

  // Event handlers (none for this node)
  group.userData.handlers = {};

  // Cleanup function
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (material.map) material.map.dispose();
    // Remove any GSAP timelines (none created)
    group.traverse((child) => {
      if (child.isMesh) {
        child.geometry?.dispose();
        if (child.material) {
          child.material.dispose();
          if (child.material.map) child.material.map.dispose();
        }
      }
    });
  };

  return group;
}
